type Db = Parameters<Parameters<typeof transaction>[0]>[0];
type User = ReturnType<typeof currentUser>;
type Row = Record<string, unknown>;
type Kind = 'text' | 'date' | 'number' | 'bool';

interface FieldDef {
  key: string;
  col: string;
  label: string;
  kind: Kind;
  max?: number;
  required?: boolean;
  // 변경 이력에 값을 남기지 않는다 (개인정보)
  secret?: boolean;
  // 목록 응답에 넣지 않는다
  noList?: boolean;
}

interface Resource {
  table: string;
  idCol: string;
  idKey: string;
  label: string;
  fields: FieldDef[];
  notFoundCode?: string;
  notFoundMessage?: string;
  pairs?: [string, string][];
  accessLog?: string;
}

const ROLE = '인사 담당자';
