const MAX_SIZE = 200;
const ID_PATTERN = /^[0-9]{1,18}$/;
const DATE_PATTERN = /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/;

function field(key: string, col: string, label: string, kind: Kind, extra: Partial<FieldDef> = {}): FieldDef {
  return { key, col, label, kind, ...extra };
}

