function isBlank(value: unknown): boolean {
  return value === undefined || value === null || (typeof value === 'string' && value.trim() === '');
}

function idOf(value: unknown, name: string): string {
  const text = typeof value === 'number' ? String(value) : value;
  if (typeof text !== 'string' || !ID_PATTERN.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', `${name} 값이 올바르지 않습니다.`);
  }
  return text;
}

function countParam(value: unknown, fallback: number, min: number, name: string): number {
  if (isBlank(value)) {
    return fallback;
  }
  const text = String(value);
  if (!/^[0-9]+$/.test(text) || Number(text) < min) {
    throw new ApiError(400, 'VALIDATION_FAILED', `${name} 값이 올바르지 않습니다.`);
  }
  return Number(text);
}

function invalid(def: FieldDef): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', `${def.label} 값이 올바르지 않습니다.`);
}

function cleanValue(def: FieldDef, value: unknown): unknown {
  if (def.kind === 'bool') {
    if (typeof value !== 'boolean') {
      throw invalid(def);
    }
    return value;
  }
  if (def.kind === 'number') {
    const n = typeof value === 'number' ? value : typeof value === 'string' ? Number(value) : NaN;
    if (!Number.isFinite(n) || n < 0) {
      throw invalid(def);
    }
    return n;
  }
  if (typeof value !== 'string') {
    throw invalid(def);
  }
  const text = value.trim();
  if (def.kind === 'date' && !DATE_PATTERN.test(text)) {
    throw invalid(def);
  }
  if (def.max !== undefined && text.length > def.max) {
    throw invalid(def);
  }
  return text;
}

function labelOf(res: Resource, key: string): string {
  const def = res.fields.find((f) => f.key === key);
  return def ? def.label : key;
}

function checkPairs(res: Resource, merged: Row): void {
  for (const [from, to] of res.pairs ?? []) {
    const a = merged[from];
    const b = merged[to];
    if (typeof a === 'string' && typeof b === 'string' && b < a) {
      throw new ApiError(400, 'VALIDATION_FAILED', `${labelOf(res, to)}은(는) ${labelOf(res, from)}보다 빠를 수 없습니다.`);
    }
  }
}

function selectExpr(def: FieldDef): string {
  const column = def.kind === 'date' ? `to_char(${def.col}, 'YYYY-MM-DD')` : def.col;
  return `${column} AS "${def.key}"`;
}

function paramExpr(def: FieldDef): string {
  if (def.kind === 'date') {
    return `CAST(:${def.key} AS date)`;
  }
  if (def.kind === 'number') {
    return `CAST(:${def.key} AS numeric)`;
  }
  if (def.kind === 'bool') {
    return `CAST(:${def.key} AS boolean)`;
  }
  return `:${def.key}`;
}

function describe(res: Resource, row: Row): string {
  return res.fields
    .filter((f) => row[f.key] !== undefined)
    .map((f) => `${f.key}=${f.secret ? '(비공개)' : String(row[f.key] ?? '')}`)
    .join(', ');
}

async function writeHistory(db: Db, userId: string, res: Resource, targetId: string, content: string): Promise<void> {
  await db.execute(
    `INSERT INTO change_history (changer_id, target_type, target_id, changed_at, change_content, created_at, updated_at)
     VALUES (CAST(:userId AS bigint), :targetType, CAST(:targetId AS bigint), now(), :content, now(), now())`,
    { userId, targetType: res.table, targetId, content },
  );
}

async function readRow(db: Db, res: Resource, id: string): Promise<Row | undefined> {
  const columns = res.fields.map(selectExpr).join(', ');
  const rows = await db.query(
    `SELECT ${columns} FROM ${res.table} WHERE ${res.idCol} = CAST(:id AS bigint)`,
    { id },
  );
  return rows[0] as Row | undefined;
}

function notFound(res: Resource): ApiError {
  return new ApiError(404, res.notFoundCode ?? 'NOT_FOUND', res.notFoundMessage ?? '정보가 없습니다.');
}

async function listRows(req: Request, user: User, res: Resource) {
  const query = checks.queryOf(req.query);
  const employeeId = idOf(query['employeeId'], '임직원');
  const page = countParam(query['page'], 0, 0, 'page');
  const size = Math.min(countParam(query['size'], DEFAULT_SIZE, 1, 'size'), MAX_SIZE);
  return transaction(async (db) => {
    if (res.accessLog) {
      await db.execute(
        `INSERT INTO personal_info_access_log (employee_id, target_employee_id, target_info_type, accessed_at, created_at, updated_at)
         VALUES (CAST(:userId AS bigint), CAST(:employeeId AS bigint), :infoType, now(), now(), now())`,
        { userId: user.id, employeeId, infoType: res.accessLog },
      );
    }
    const columns = [`${res.idCol} AS "${res.idKey}"`, ...res.fields.filter((f) => !f.noList).map(selectExpr)].join(', ');
    const items = await db.query(
      `SELECT ${columns} FROM ${res.table} WHERE employee_id = CAST(:employeeId AS bigint)
       ORDER BY ${res.idCol} LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
      { employeeId, size, offset: page * size },
    );
    const counted = await db.query(
      `SELECT COUNT(*) AS "total" FROM ${res.table} WHERE employee_id = CAST(:employeeId AS bigint)`,
      { employeeId },
    );
    return { items, page, size, total: Number(counted[0]['total']) };
  });
}

async function createRow(req: Request, user: User, res: Resource) {
  const data = checks.inputOf(req.body);
  if (isBlank(data['employeeId'])) {
    throw new ApiError(422, 'REQUIRED_FIELD_MISSING', '임직원 항목이 필요합니다.');
  }
  const employeeId = idOf(data['employeeId'], '임직원');
  const values: Row = {};
  for (const def of res.fields) {
    const raw = data[def.key];
    if (isBlank(raw)) {
      if (def.required) {
        throw new ApiError(422, 'REQUIRED_FIELD_MISSING', `${def.label} 항목이 필요합니다.`);
      }
      continue;
    }
    values[def.key] = cleanValue(def, raw);
  }
  checkPairs(res, values);
  return transaction(async (db) => {
    const employees = await db.query(
      'SELECT employee_id FROM employee WHERE employee_id = CAST(:employeeId AS bigint)',
      { employeeId },
    );
    if (employees.length === 0) {
      throw new ApiError(404, 'EMPLOYEE_NOT_FOUND', '임직원을 찾을 수 없습니다.');
    }
    const used = res.fields.filter((f) => values[f.key] !== undefined);
    const columnList = ['employee_id', ...used.map((f) => f.col), 'created_at', 'updated_at'].join(', ');
    const valueList = ['CAST(:employeeId AS bigint)', ...used.map(paramExpr), 'now()', 'now()'].join(', ');
    const rows = await db.query(
      `INSERT INTO ${res.table} (${columnList}) VALUES (${valueList}) RETURNING ${res.idCol} AS "id"`,
      { ...values, employeeId },
    );
    const id = String(rows[0]['id']);
    await writeHistory(db, user.id, res, id, `등록: ${describe(res, values)}`);
    return { [res.idKey]: Number(id) };
  });
}

async function updateRow(req: Request, user: User, res: Resource, rawId: string) {
  const id = idOf(rawId, res.idKey);
  const data = checks.inputOf(req.body);
  const changes: Row = {};
  for (const def of res.fields) {
    const raw = data[def.key];
    if (raw === undefined) {
      continue;
    }
    if (isBlank(raw)) {
      if (def.required) {
        throw new ApiError(400, 'VALIDATION_FAILED', `${def.label}은(는) 비울 수 없습니다.`);
      }
      changes[def.key] = null;
      continue;
    }
    changes[def.key] = cleanValue(def, raw);
  }
  if (Object.keys(changes).length === 0) {
    throw new ApiError(400, 'VALIDATION_FAILED', '수정할 항목이 없습니다.');
  }
  return transaction(async (db) => {
    const before = await readRow(db, res, id);
    if (!before) {
      throw notFound(res);
    }
    checkPairs(res, { ...before, ...changes });
    const params: Row = { id };
    const sets: string[] = [];
    const diffs: string[] = [];
    for (const def of res.fields) {
      if (changes[def.key] === undefined) {
        continue;
      }
      const value = changes[def.key];
      if (value === null) {
        sets.push(`${def.col} = NULL`);
      } else {
        sets.push(`${def.col} = ${paramExpr(def)}`);
        params[def.key] = value;
      }
      diffs.push(
        def.secret
          ? `${def.key}: 변경됨`
          : `${def.key}: ${String(before[def.key] ?? '')} → ${String(value ?? '')}`,
      );
    }
    await db.execute(
      `UPDATE ${res.table} SET ${sets.join(', ')}, updated_at = now() WHERE ${res.idCol} = CAST(:id AS bigint)`,
      params,
    );
    await writeHistory(db, user.id, res, id, `수정: ${diffs.join(', ')}`);
    return { [res.idKey]: Number(id) };
  });
}

async function deleteRow(user: User, res: Resource, rawId: string) {
  const id = idOf(rawId, res.idKey);
  return transaction(async (db) => {
    const before = await readRow(db, res, id);
    if (!before) {
      throw notFound(res);
    }
    await db.execute(`DELETE FROM ${res.table} WHERE ${res.idCol} = CAST(:id AS bigint)`, { id });
    await writeHistory(db, user.id, res, id, `삭제: ${describe(res, before)}`);
    return {};
  });
}

