const EMPTY_PAGE: Page = { items: [], page: 0, size: PAGE_SIZE, total: 0 };

export default function FnSfr01205Page({ role, notify }: PageProps) {
  const [employeeInput, setEmployeeInput] = useState<number | string>('');
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [sectionKey, setSectionKey] = useState('family');
  const [pageNo, setPageNo] = useState(0);
  const [mode, setMode] = useState<'create' | 'edit' | 'delete' | null>(null);
  const [target, setTarget] = useState<Row | null>(null);
  const [values, setValues] = useState<Row>({});

  const section = SECTIONS.find((s) => s.key === sectionKey) ?? SECTIONS[0];

  const { data, error, loading, reload } = useData<Page>(async () => {
    if (employeeId === '') {
      return EMPTY_PAGE;
    }
    return call<Page>('GET', section.path, role, undefined, { employeeId, page: pageNo, size: PAGE_SIZE });
  }, [role, employeeId, section.key, pageNo]);

  function search() {
    setPageNo(0);
    setEmployeeId(employeeInput);
    reload();
  }

  function reset() {
    setEmployeeInput('');
    setEmployeeId('');
    setPageNo(0);
  }

  function closeDrawer() {
    setMode(null);
    setTarget(null);
  }

  function openCreate() {
    const initial: Row = {};
    for (const f of section.fields) {
      if (f.kind === 'bool') {
        initial[f.key] = 'false';
      }
    }
    setValues(initial);
    setTarget(null);
    setMode('create');
  }

  function openEdit(row: Row) {
    const initial: Row = {};
    for (const f of section.fields) {
      const v = row[f.key];
      initial[f.key] = f.kind === 'bool' ? String(v === true) : (v ?? '');
    }
    setValues(initial);
    setTarget(row);
    setMode('edit');
  }

  function openDelete(row: Row) {
    setTarget(row);
    setMode('delete');
  }

  function buildBody(editing: boolean): Row {
    const body: Row = {};
    for (const f of section.fields) {
      const v = values[f.key];
      const blank = v === undefined || v === null || v === '';
      if (blank) {
        if (f.required) {
          throw new Error(`필수 항목(${f.label})을 입력해 주세요.`);
        }
        if (editing && !f.omitBlank) {
          body[f.key] = '';
        }
        continue;
      }
      body[f.key] = f.kind === 'bool' ? v === 'true' : v;
    }
    return body;
  }

  async function submitSave() {
    if (mode === 'create') {
      const body = buildBody(false);
      body.employeeId = employeeId;
      await call('POST', section.path, role, body);
      notify(`${section.title} 정보를 등록했습니다.`);
    } else if (target) {
      const body = buildBody(true);
      await call('PATCH', `${section.path}/${String(target[section.idKey])}`, role, body);
      notify(`${section.title} 정보를 수정했습니다.`);
    }
    closeDrawer();
    reload();
  }

  async function submitDelete() {
    if (!target) {
      return;
    }
    await call('DELETE', `${section.path}/${String(target[section.idKey])}`, role);
    notify(`${section.title} 정보를 삭제했습니다.`);
    closeDrawer();
    reload();
  }

  function renderInput(f: FieldDef) {
    const value = values[f.key] ?? '';
    const set = (v: unknown) => setValues({ ...values, [f.key]: v });
    if (f.kind === 'date') {
      return <DateInput value={value} onChange={set} />;
    }
    if (f.kind === 'number') {
      return <NumberInput value={value} onChange={set} />;
    }
    if (f.kind === 'bool') {
      return <Select value={value} onChange={set} options={[['true', '예'], ['false', '아니오']]} />;
    }
    return <TextInput value={value} onChange={set} multiline={f.kind === 'long'} />;
  }

  const columns: Column[] = [...section.columns(role)];
  if (!section.readOnly) {
    columns.push({
      key: 'actions',
      label: '처리',
      render: (row) => (
        <span>
          <button type="button" className="ghost" onClick={() => openEdit(row)}>수정</button>
          {' '}
          <button type="button" className="ghost" onClick={() => openDelete(row)}>삭제</button>
        </span>
      ),
    });
  }

  const page = data ?? EMPTY_PAGE;
  const emptyText = employeeId === ''
    ? '임직원을 고른 뒤 조회를 눌러 주세요.'
    : '아직 등록한 내역이 없습니다.';

  return (
    <div>
      <h1>인사기록카드 상세정보</h1>
      <Filters onSearch={search} onReset={reset}>
        <Field label="임직원" required>
          <LookupSelect table="employee" role={role} value={employeeInput} onChange={setEmployeeInput} placeholder="임직원 선택" />
        </Field>
        <Field label="정보 항목">
          <Select
            value={sectionKey}
            onChange={(v) => {
              setSectionKey(v);
              setPageNo(0);
            }}
            options={SECTIONS.map((s): [string, string] => [s.key, s.title])}
          />
        </Field>
      </Filters>
      <Band total={page.total}>
        {!section.readOnly && employeeId !== '' && (
          <button type="button" onClick={openCreate}>{section.title} 등록</button>
        )}
      </Band>
      {error !== '' && <p>{error}</p>}
      {loading && <p>불러오는 중입니다.</p>}
      <DataTable columns={columns} rows={page.items} empty={emptyText} />
      <Pager page={page.page} size={page.size} total={page.total} onPage={setPageNo} />
      {(mode === 'create' || mode === 'edit') && (
        <Drawer title={`${section.title} ${mode === 'create' ? '등록' : '수정'}`} onClose={closeDrawer}>
          <Form onSubmit={submitSave} submit={mode === 'create' ? '등록' : '저장'}>
            {section.fields.map((f) => (
              <Field key={f.key} label={f.label} required={f.required} wide={f.kind === 'long'}>
                {renderInput(f)}
              </Field>
            ))}
          </Form>
        </Drawer>
      )}
      {mode === 'delete' && (
        <Drawer title={`${section.title} 삭제`} onClose={closeDrawer}>
          <Form
            onSubmit={submitDelete}
            submit="삭제"
            danger
            note="삭제하면 되돌릴 수 없습니다. 삭제 내용은 변경 이력에 남습니다."
          />
        </Drawer>
      )}
    </div>
  );
}
